import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.Emote{EntityRuntimeID: 7, EmoteID: "emote.happy", EmoteLength: 20,
# XUID: "2535413418839840", PlatformID: "", Flags: packet.EmoteFlagServerSide}
SERVER_SIDE = bytes.fromhex("070b656d6f74652e68617070791410323533353431333431383833393834300001")

# generated by gophertunnel b8bd735:
# &packet.Emote{EntityRuntimeID: 300, EmoteID: "e", EmoteLength: 200, XUID: "x", PlatformID: "p", Flags: 0xff}
WIDE = bytes.fromhex("ac020165c80101780170ff")

GOLDENS = [
    pytest.param(
        v2225.EmotePacket(
            runtime_id=7,
            piece_id="emote.happy",
            emote_ticks=20,
            xuid="2535413418839840",
            platform_id="",
            flags=v2225.EmotePacket.Flags.SERVER_SIDE,
        ),
        SERVER_SIDE,
        id="server-side",
    ),
    pytest.param(
        v2225.EmotePacket(runtime_id=300, piece_id="e", emote_ticks=200, xuid="x", platform_id="p", flags=0xFF),
        WIDE,
        id="ticks-widen-to-a-varint-and-flags-stay-one-byte",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_emote_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_emote_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
